<div class="d-flex justify-content-between align-items-center mb-4"><h1>💰 Historial de Ventas</h1><a href="index.php?controller=venta&action=registrar" class="btn btn-primary">➕ Nueva Venta</a></div><div class="card"><div class="card-body table-responsive"><?php if(empty($ventas)): ?><div class="alert alert-info text-center">No hay ventas registradas.</div><?php else: ?><table class="table table-hover table-striped align-middle"><thead class="table-primary"><tr><th>ID Venta</th><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Total</th><?php if(($_SESSION['user_role']??'')==='admin'): ?><th>Acciones</th><?php endif; ?></tr></thead><tbody><?php $totalGeneral=0; foreach($ventas as $v): $totalGeneral+=(float)$v['Total']; ?><tr><td>#<?= (int)$v['ID_Venta'] ?></td><td><?= date('d/m/Y H:i',strtotime($v['Fecha_Venta'])) ?></td><td><?= htmlspecialchars($v['ProductoNombre'],ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$v['Cantidad'] ?></td><td><strong>S/<?= number_format((float)$v['Total'],2) ?></strong></td><?php if(($_SESSION['user_role']??'')==='admin'): ?><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary edit-venta" data-bs-toggle="modal" data-bs-target="#editVenta" data-id="<?= (int)$v['ID_Venta'] ?>" data-producto="<?= (int)$v['ID_Producto'] ?>" data-cantidad="<?= (int)$v['Cantidad'] ?>">Actualizar</button><form class="d-inline" method="post" action="index.php?controller=venta&action=eliminar" onsubmit="return confirm('¿Eliminar venta y restituir stock?')"><input type="hidden" name="id" value="<?= (int)$v['ID_Venta'] ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody><tfoot class="table-light"><tr><th colspan="4" class="text-end">Total General:</th><th>S/<?= number_format($totalGeneral,2) ?></th><?php if(($_SESSION['user_role']??'')==='admin'): ?><th></th><?php endif; ?></tr></tfoot></table><small class="text-muted">Total de ventas: <?= count($ventas) ?></small><?php endif; ?></div></div>
<?php if(($_SESSION['user_role']??'')==='admin'): ?><div class="modal fade" id="editVenta" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="index.php?controller=venta&action=actualizar"><div class="modal-header"><h5 class="modal-title">Actualizar venta</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="ID_Venta" id="venId"><div class="mb-3"><label class="form-label">Producto</label><select class="form-select" name="ID_Producto" id="venProd" required><?php foreach($productos as $p): ?><option value="<?= (int)$p['ID_Producto'] ?>"><?= htmlspecialchars($p['Nombre'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Cantidad</label><input class="form-control" type="number" min="1" name="Cantidad" id="venCant" required></div><p class="form-text">El total se recalcula con el precio actual del producto.</p></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form></div></div><script>document.querySelectorAll('.edit-venta').forEach(b=>b.addEventListener('click',function(){document.getElementById("venId").value=this.dataset.id;document.getElementById("venProd").value=this.dataset.producto;document.getElementById("venCant").value=this.dataset.cantidad;}));</script><?php endif; ?>
